// @vegastack person-hover-card@0.25.7 sha256-qmbqT7XJNpRVlAZghYqTec2Ii6puKT8cx+XGjruj8lw=

"use client";

import * as React from "react";
import { cn } from "@vegastack/design";
import { AvatarGroup, AvatarGroupCount } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  PersonAvatar as BasePersonAvatar,
  type Person as BasePerson,
} from "@/components/ui/person-avatar";
import { PersonBadge } from "@/components/ui/searchable-select";
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from "@/components/ui/hover-card";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

/* ------------------------------------------------------------------------------------------------
 * PersonHoverCard — a person behind an avatar: hover or focus (tap on touch) opens a card with a
 * 32px avatar (`PersonAvatar`: the photo, else initials on the person's hue) with the name and a muted email stacked beside it. AvatarStack stacks up to `max` of them (the Avatar
 * group recipe) with the rest behind a "+N" that opens the same rows in a list. A person without
 * an account (a free-text participant) shows initials and just the name. A team (`kind: "team"`)
 * stacks and lists the same way, drawn as its rounded-square team tile.
 * ----------------------------------------------------------------------------------------------*/

/** A person — re-exported from `person-avatar`, their home, for existing imports. */
export type Person = BasePerson;

/** `PersonAvatar` — re-exported from `person-avatar`, its home, for existing imports. @example <PersonAvatar person={{ name: "Asha Rao", hue: "blue" }} /> */
export const PersonAvatar = BasePersonAvatar;

/** Props for `PersonCard`. */
export interface PersonCardProps extends React.ComponentPropsWithRef<"div"> {
  /** The person. */
  person: Person;
  /**
   * `card` — the hover card's body: a 32px avatar with the name and email stacked beside it.
   * `row` — one line of a list: a smaller avatar beside them.
   * @default "card"
   */
  layout?: "card" | "row";
}

/** `PersonCard` — a person's avatar, name and muted email. @example <PersonCard person={{ name: "Asha Rao", email: "asha@acme.com" }} /> */
export function PersonCard({
  person,
  layout = "card",
  className,
  ...props
}: PersonCardProps) {
  return (
    <div
      data-slot="person-card"
      data-layout={layout}
      className={cn(
        "flex min-w-0 items-center",
        layout === "card" ? "gap-2.5" : "gap-2",
        className,
      )}
      {...props}
    >
      <PersonAvatar
        person={person}
        size={layout === "card" ? "default" : "sm"}
      />
      <div className="flex min-w-0 flex-col">
        <span className="flex min-w-0 flex-wrap items-center gap-x-1.5">
          <span className="text-sm font-medium wrap-anywhere">
            {person.name}
          </span>
          <PersonBadge badge={person.badge} />
        </span>
        {person.email ? (
          <span className="text-xs wrap-anywhere text-muted-foreground">
            {person.email}
          </span>
        ) : null}
      </div>
    </div>
  );
}

/** Props for `PersonHoverCard`. */
export interface PersonHoverCardProps {
  /** The person. */
  person: Person;
  /**
   * The trigger — a `PersonAvatar` (`trigger="avatar"`) or the person's name (`trigger="name"`).
   */
  children: React.ReactNode;
  /**
   * `avatar` — the children sit in a round ghost button named by the person. `name` — the
   * children are inline text (a comment's author, an activity's actor) in a plain text button.
   * @default "avatar"
   */
  trigger?: "avatar" | "name";
  /** Classes for the trigger button. @default undefined */
  className?: string;
}

/**
 * `PersonHoverCard` — hover or focus the trigger (tap it on touch) for the person's card.
 *
 * @example
 * <PersonHoverCard person={p}><PersonAvatar person={p} /></PersonHoverCard>
 */
export function PersonHoverCard({
  person,
  children,
  trigger = "avatar",
  className,
}: PersonHoverCardProps) {
  const [open, setOpen] = React.useState(false);
  return (
    <HoverCard open={open} onOpenChange={setOpen}>
      <HoverCardTrigger
        render={
          trigger === "name" ? (
            <button
              type="button"
              data-slot="person-hover-card-name"
              className={cn(
                // A name in a sentence (a button computes `inline` as `inline-block`): a target in
                // a block of text, sized by its line (WCAG 2.2 §2.5.8's inline exception). Where
                // a flex row blockifies it, the host pads it to 24px.
                "inline min-w-0 cursor-default rounded-sm text-start font-medium text-foreground focus-visible:bg-accent",
                className,
              )}
              onClick={() => setOpen((o) => !o)}
            />
          ) : (
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={person.name}
              className={cn(
                person.kind === "team" ? "rounded-md" : "rounded-full",
                className,
              )}
              onClick={() => setOpen((o) => !o)}
            />
          )
        }
      >
        {children}
      </HoverCardTrigger>
      <HoverCardContent align="start" className="w-60 p-2">
        <PersonCard person={person} />
      </HoverCardContent>
    </HoverCard>
  );
}

/** Props for `AvatarStack`. */
export interface AvatarStackProps {
  /** The people, in order. */
  people: readonly Person[];
  /**
   * How many avatars show before the rest go behind "+N".
   * @default 5
   */
  max?: number;
  /**
   * The total number of people, when `people` is only the first page of them (a space with 14
   * members, 5 loaded). "+N" counts from it, so the stack and its count always agree.
   * @default people.length
   */
  total?: number;
  /** The group's accessible name. @default "People" */
  label?: string;
  /**
   * A footer action in the list popover, such as "Manage access" that opens the Share dialog.
   * @default undefined
   */
  footer?: React.ReactNode;
  /** Classes for the group. @default undefined */
  className?: string;
}

/**
 * `AvatarStack` — truly stacked 24px avatars (overlapping, a ring in the background colour) with
 * "+N" past `max`. Hovering an avatar previews that person (`PersonCard`); the stack itself is one
 * button — click, tap or Enter — that lists everyone as `PersonCard` rows. One control for the
 * whole stack keeps a full 24px target without spreading the avatars apart.
 *
 * @example
 * <AvatarStack people={participants} label="Participants" />
 */
export function AvatarStack({
  people,
  max = 5,
  total,
  label = "People",
  footer,
  className,
}: AvatarStackProps) {
  const shown = people.slice(0, max);
  const count = Math.max(total ?? people.length, people.length);
  const rest = count - shown.length;
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            variant="ghost"
            data-slot="avatar-stack"
            aria-label={`${label}: ${people.map((p) => p.name).join(", ")}${
              count > people.length ? ` and ${count - people.length} more` : ""
            }`}
            className={cn(
              "h-auto rounded-full p-0.5 active:not-aria-[haspopup]:translate-y-0",
              className,
            )}
          />
        }
      >
        {/* A 4px overlap (not upstream's 8px): each 24px avatar keeps 20px visible, so two
            initials are never cut by the next avatar. */}
        <AvatarGroup aria-hidden className="-space-x-1">
          {shown.map((p, i) => (
            <HoverCard key={`${p.name}-${i}`}>
              <HoverCardTrigger
                render={
                  <span
                    className={cn(
                      "inline-flex",
                      p.kind === "team" ? "rounded-md" : "rounded-full",
                    )}
                  />
                }
              >
                <PersonAvatar person={p} className="ring-2 ring-background" />
              </HoverCardTrigger>
              <HoverCardContent align="start" className="w-60 p-2">
                <PersonCard person={p} />
              </HoverCardContent>
            </HoverCard>
          ))}
          {rest > 0 ? <AvatarGroupCount>+{rest}</AvatarGroupCount> : null}
        </AvatarGroup>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-60 p-2">
        <ul aria-label={label} className="flex flex-col gap-2">
          {people.map((p, i) => (
            <li key={`${p.name}-${i}`}>
              <PersonCard person={p} />
            </li>
          ))}
        </ul>
        {count > people.length ? (
          <p className="px-1 pt-2 text-xs text-muted-foreground">
            and {count - people.length} more
          </p>
        ) : null}
        {footer != null ? (
          <div
            data-slot="avatar-stack-footer"
            className="-mx-2 -mb-2 mt-2 border-t border-border p-1"
          >
            {footer}
          </div>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}
